{
  args: {
    children: 'Label',
    variant: undefined,
    color: undefined,
    size: undefined
  }
}

{
  args: {
    children: 'Label'
  },
  render: args => <BadgeWrapper>
      <Badge variant="outline" color="primary">
        {args.children}
      </Badge>
      <Badge variant="filled" color="primary">
        {args.children}
      </Badge>
      <Badge variant="light" color="primary">
        {args.children}
      </Badge>
    </BadgeWrapper>
}

{
  args: {
    children: 'Label'
  },
  render: args => <BadgeWrapper>
      <Badge size="small">{args.children}</Badge>
      <Badge size="medium">{args.children}</Badge>
      <Badge size="large">{args.children}</Badge>
    </BadgeWrapper>
}

{
  args: {
    children: '5',
    variant: 'filled',
    color: 'primary',
    rounded: true
  },
  render: args => <BadgeWrapper>
      <Badge variant="filled" color="primary" rounded>
        {args.children}
      </Badge>
      <Badge variant="filled" color="primary" rounded>
        999+
      </Badge>
    </BadgeWrapper>
}
